service.method:

		UPDATE SUPIM
		   SET ITEM_CODE   = ${ITEM_CODE}
			  ,ITEM_NAME   = ${ITEM_NAME}
			  ,ITEM_TYPE   = ${ITEM_TYPE}
			  ,ITEM_SEQ    = ${ITEM_SEQ}
			  ,CONT_TYPE   = ${CONT_TYPE}
			  ,DES_FILE_PATH = ${DES_FILE_PATH}
			  ,CLASS = ${CLASS}
			  ,METHOD = ${METHOD}
			  ,DISPLAY_TEMPLATE = ${DISPLAY_TEMPLATE}
			  ,DISPLAY_EDIT = ${DISPLAY_EDIT}
			  ,SEAL_WIDTH	= ${SEAL_WIDTH}
			  ,SEAL_HEIGHT	= ${SEAL_HEIGHT}
			  ,PRE_FILE_PATH = ${PRE_FILE_PATH}
			  ,CATEGORY = ${CATEGORY}
              ,ATTACH_TYPE = ${ATTACH_TYPE}
              ,ITEM_FORMAT = ${ITEM_FORMAT}
		 WHERE #DB_OWNER#NVL(DEL_FLAG, 'N') = 'N' 
		   AND HOUSE_CODE   = ${session.HOUSE_CODE}
		   AND COMPANY_CODE = ${session.COMPANY_CODE}
		   AND ITEM_NO      = ${ITEM_NO}


UPDATE SUPIM
   SET DEL_FLAG = 'Y'
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND ITEM_NO      = ${ITEM_NO}


 	SELECT ITEM_NO
 		FROM SUPIM
		WHERE HOUSE_CODE = ${session.HOUSE_CODE}
			AND COMPANY_CODE = ${session.COMPANY_CODE}
			AND ITEM_NO = ${ITEM_NO}
			AND ITEM_CODE = ${ITEM_CODE}
